const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define China geometry
  const china = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'China'));

  // 2. Load MODIS LAI data
  const lai = ee.ImageCollection('MODIS/006/MOD15A2H')
    .select('Lai_500m');

  // 3. Filter for 2000
  const lai2000 = lai
    .filterDate('2000-01-01', '2000-12-31')
    .filterBounds(china);

  // 4. Filter for 2017
  const lai2017 = lai
    .filterDate('2017-01-01', '2017-12-31')
    .filterBounds(china);

  // Check collection sizes
  const size2000 = await lai2000.size().getInfo();
  const size2017 = await lai2017.size().getInfo();

  print(`2000 Images: ${size2000}, 2017 Images: ${size2017}`);

  if (size2000 === 0 || size2017 === 0) {
    print('Empty Collection');
    print('C1');
    return;
  }

  // 5. Calculate mean LAI for each year
  const img2000 = lai2000.mean();
  const img2017 = lai2017.mean();

  // 6. Compute valid pixel counts and mean values
  const stats2000 = img2000.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: china,
    scale: 500,
    maxPixels: 1e9
  });

  const stats2017 = img2017.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: china,
    scale: 500,
    maxPixels: 1e9
  });

  const mean2000 = await stats2000.getInfo();
  const mean2017 = await stats2017.getInfo();

  const lai2000Val = mean2000['Lai_500m_mean'];
  const lai2017Val = mean2017['Lai_500m_mean'];
  const count2000 = mean2000['Lai_500m_count'];
  const count2017 = mean2017['Lai_500m_count'];

  print(`2000 LAI: ${(lai2000Val || 0).toFixed(2)}, Pixels: ${count2000}`);
  print(`2017 LAI: ${(lai2017Val || 0).toFixed(2)}, Pixels: ${count2017}`);

  // 7. Validation
  if (count2000 === 0 || count2017 === 0) {
    print('No Valid Pixels');
    print('C2');
    return;
  }

  if (lai2000Val === null || lai2017Val === null || 
      lai2000Val === undefined || lai2017Val === undefined ||
      lai2000Val < 0 || lai2000Val > 10 || 
      lai2017Val < 0 || lai2017Val > 10) {
    print('Calculation Failure');
    print('C3');
    return;
  }

  // 8. Compare
  const increase = lai2017Val > lai2000Val;
  print(`Change: ${(lai2017Val - lai2000Val).toFixed(3)}`);

  if (increase) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
